import { OrderState, OrderStateType } from './OrderState';
import { OrderItem } from './OrderItem';

export class Order {
  private constructor(
    readonly id: string,
    private state: OrderState,
    readonly items: OrderItem[],
    readonly createdAt: Date,
  ) {}

  static create(id: string, items: OrderItem[]): Order {
    if (items.length === 0) {
      throw new Error('Order must contain at least one item');
    }
    return new Order(id, OrderState.create('placed'), items, new Date());
  }

  static fromState(id: string, state: OrderStateType, items: OrderItem[], createdAt: Date): Order {
    return new Order(id, OrderState.create(state), items, createdAt);
  }

  getState(): OrderState {
    return this.state;
  }

  getStateValue(): OrderStateType {
    return this.state.value;
  }

  transitionTo(nextState: OrderStateType): void {
    if (!this.state.canTransitionTo(nextState)) {
      throw new Error(
        `Cannot transition from ${this.state.value} to ${nextState}`,
      );
    }
    this.state = OrderState.create(nextState);
  }

  cancel(): void {
    if (!this.state.canBeCancelled()) {
      throw new Error(`Cannot cancel order in state ${this.state.value}`);
    }
    this.state = OrderState.create('placed');
  }

  isCancellable(): boolean {
    return this.state.canBeCancelled();
  }
}

