export type OrderStateType = 'placed' | 'paid' | 'packed' | 'shipped' | 'delivered';

export const ORDER_STATE_SEQUENCE: OrderStateType[] = ['placed', 'paid', 'packed', 'shipped', 'delivered'];

export class OrderState {
  private constructor(readonly value: OrderStateType) {}

  static create(value: OrderStateType): OrderState {
    return new OrderState(value);
  }

  canTransitionTo(nextState: OrderStateType): boolean {
    const currentIndex = ORDER_STATE_SEQUENCE.indexOf(this.value);
    const nextIndex = ORDER_STATE_SEQUENCE.indexOf(nextState);
    return nextIndex === currentIndex + 1;
  }

  canBeCancelled(): boolean {
    return this.value !== 'shipped' && this.value !== 'delivered';
  }

  equals(other: OrderState): boolean {
    return this.value === other.value;
  }
}

