import { Quantity } from './Quantity';

export class Product {
  private constructor(
    readonly id: string,
    readonly name: string,
    private availableStock: Quantity,
    private reservedStock: Quantity,
  ) {}

  static create(id: string, name: string, availableStock: Quantity): Product {
    return new Product(id, name, availableStock, Quantity.create(0));
  }

  reserveStock(quantity: Quantity): void {
    if (this.availableStock.isLessThan(quantity)) {
      throw new Error(`Insufficient stock for product ${this.id}`);
    }
    this.availableStock = this.availableStock.subtract(quantity);
    this.reservedStock = this.reservedStock.add(quantity);
  }

  releaseStock(quantity: Quantity): void {
    this.reservedStock = this.reservedStock.subtract(quantity);
    this.availableStock = this.availableStock.add(quantity);
  }

  getAvailableStock(): Quantity {
    return this.availableStock;
  }

  getReservedStock(): Quantity {
    return this.reservedStock;
  }

  getTotalStock(): Quantity {
    return this.availableStock.add(this.reservedStock);
  }
}

